const metadata=new Map(canonicalCourses.filter(c=>c.subject==='Médicament & Société').map(c=>[c.id,c]))
const sectionTitles=['Repères et définitions','Mécanismes et cadre','Application en santé','Limites et controverses','Méthode d’analyse']
export const drugSocietyCourses:Course[]=units.map(u=>{const c=metadata.get(u.id);if(!c)throw new Error(`Cours canonique médicament-société absent : ${u.id}`);return{id:u.id,title:c.title,category:c.subject,tag:c.module,minutes:17,structure:null,objectives:u.objectives,sections:u.facts.map((text,i)=>({title:sectionTitles[i],text})),trap:u.trap,recall:u.recall,answer:u.answer,source:u.source,sources:[{label:u.source.includes('sante.gouv.fr')?'Ministère chargé de la santé · publicité des médicaments':u.source.includes('ema')?'EMA · réglementation européenne':u.source.includes('has-sante')?'HAS · évaluation et accès':u.source.includes('who.int')?'OMS · santé et substances':u.source.includes('fda.gov')?'FDA · histoire de la réglementation':'ANSM · sécurité du médicament',url:u.source},...(u.id==='soc-drug-history-scandals'?[{label:'NCI · exposition prénatale au DES',url:'https://www.cancer.gov/about-cancer/causes-prevention/risk/hormones/des-fact-sheet'},{label:'BMJ · affaire Mediator',url:'https://www.bmj.com/content/bmj/372/bmj.n873.full.pdf'}]:[])],prerequisites:['Pharmacologie générale','Épidémiologie et santé publique'],glossary:[['AMM','Autorisation réglementaire de commercialisation pour des indications données.'],['Pharmacovigilance','Surveillance et prévention des risques liés aux médicaments.'],['Équité d’accès','Répartition juste des possibilités de bénéficier des soins.']],caseStudy:{prompt:u.recall,answer:u.answer},review:{status:'unreviewed',updatedAt:'2026-09-23',sourcesUpdatedAt:'2026-09-23'}}})
export const drugSocietyQuestions:Question[]=units.flatMap(u=>u.qa.map(([prompt,correct,wrong1,wrong2,wrong3,w1,w2,w3],i)=>({id:`${u.id}-q${i+1}`,course:u.id,topic:'Médicament & Société',prompt,options:[correct,wrong1,wrong2,wrong3],correct:[0],why:[`Réponse correcte : ${correct}`,w1,w2,w3],difficulty:i<2?'essentiel':'application',format:'single'})))
